item.command:
/usr/bin/zsh -lc "cat > candidate.sv <<'EOF'
module TopModule (
    input  logic a,
    input  logic b,
    input  logic c,
    input  logic d,
    output logic out_sop,
    output logic out_pos
);
    assign out_sop = (~a & ~b & c) | (c & d);
    assign out_pos = c & (~a | d) & (~b | d);
endmodule
EOF
cp candidate.sv candidate_initial.sv
cat > dev_tb.sv <<'EOF'
module dev_tb;
    logic a, b, c, d;
    wire out_sop, out_pos;
    logic expected;
    integer checked = 0;
    TopModule dut (.a(a), .b(b), .c(c), .d(d),
                   .out_sop(out_sop), .out_pos(out_pos));
    task automatic check_input(input integer value);
        begin
            {a,b,c,d} = value[3:0];
            #1;
            case (value)
                2,7,15: expected = 1'b1;
                0,1,4,5,6,9,10,13,14: expected = 1'b0;
                default: expected = 1'bx;
            endcase
            if (expected "'!== 1'"'bx) begin
                checked = checked + 1;
                if (out_sop "'!== expected || out_pos !== expected)
                    $fatal(1, "FAIL input=%0d expected=%b sop=%b pos=%b",
                           value, expected, out_sop, out_pos);
            end
        end
    endtask
    initial begin
        for (integer i = 0; i < 16; i = i + 1) check_input(i);
        for (integer i = 15; i >= 0; i = i - 1) check_input(i);
        $display("PASS: %0d specified-input checks across two exhaustive sweeps", checked);
        $finish;
    end
    initial begin
        #100;
        $fatal(1, "FAIL: watchdog timeout");
    end
endmodule
EOF
 timeout 20s /home/shmin/nl2hdl/.conda_pkgs/iverilog-12.0-ha738cfc_1/bin/iverilog -g2012 -Wall -s dev_tb -o dev_sim candidate.sv dev_tb.sv > compile_initial.log 2>&1
compile_status=$?
 echo "$compile_status" > compile_initial.exit
 if [ "$compile_status" -eq 0 ]; then
 timeout 20s /home/shmin/nl2hdl/.conda_pkgs/iverilog-12.0-ha738cfc_1/bin/vvp dev_sim > simulation_initial.log 2>&1
 echo "$?" > simulation_initial.exit
 fi
cat compile_initial.log simulation_initial.log'

